update public.institutions set
  feedback_summary_student = 'Небольшая театральная школа под руководством Константина Райкина при театре «Сатирикон» с почти исключительно положительными отзывами: семейная атмосфера, мастер-классы, сильные педагоги-практики. Выпускники востребованы в московских театрах. Обучение платное, публичной негативной критики почти не встречается.',
  feedback_positive_highlights = '{"семейная атмосфера под руководством Константина Райкина","сильные педагоги-практики и мастер-классы","востребованность выпускников в московских театрах"}',
  feedback_negative_highlights = '{}',
  feedback_based_on_count = 3, feedback_generated_at = now(), updated_at = now()
where name = 'Высшая школа сценических искусств (Театральная школа Константина Райкина)' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Старейшая театральная школа Москвы («школа русского сценического реализма») с сильно положительными отзывами: невероятные педагоги, дружелюбная приёмная комиссия, талантливое и взаимоподдерживающее студенческое сообщество. Поступление описывается как морально тяжёлое испытание с почти непрерывными турами весной.',
  feedback_positive_highlights = '{"сильная актёрская школа русского реализма","дружелюбная приёмная комиссия","поддерживающее студенческое сообщество"}',
  feedback_negative_highlights = '{"морально тяжёлый, изматывающий процесс поступления"}',
  feedback_based_on_count = 3, feedback_generated_at = now(), updated_at = now()
where name = 'Высшее театральное училище (институт) им. М.С.Щепкина при Государственном академическом Малом театре России' and city = 'Москва';

update public.institutions set
  feedback_summary_student = 'Относительно молодой факультет МГУ, активно развивающийся (новые кафедры, направления вроде цифровой социологии). Отзывы в основном положительные: отзывчивый деканат, посильное поступление, ощутимое развитие программы за последние годы. Из минусов — нехватка практики, которую сложно совмещать с работой.',
  feedback_positive_highlights = '{"отзывчивый деканат","активное развитие программы и новых кафедр"}',
  feedback_negative_highlights = '{"нехватка практики, сложно совмещать с работой"}',
  feedback_based_on_count = 3, feedback_generated_at = now(), updated_at = now()
where name = 'Высшая школа современных социальных наук МГУ имени М.В. Ломоносова' and city = 'Москва';
